/** A theme is a light and a dark palette that share one role set, plus the terminal ANSI slots. */
@Immutable
data class RiffetTheme(
    val id: String,
    val light: RiffetColors,
    val dark: RiffetColors,
    val ansiLight: RiffetAnsi,
    val ansiDark: RiffetAnsi,
)

/** Every built-in theme, in the order the pickers list them. */
val RiffetThemes: List<RiffetTheme> = listOf(
    RiffetTheme("riffet", riffetLight, riffetDark, riffetLightAnsi, riffetDarkAnsi),
    RiffetTheme("solarized", solarizedLight, solarizedDark, solarizedLightAnsi, solarizedDarkAnsi),
    RiffetTheme("catppuccin", catppuccinLight, catppuccinDark, catppuccinLightAnsi, catppuccinDarkAnsi),
    RiffetTheme("rose-pine", rosePineLight, rosePineDark, rosePineLightAnsi, rosePineDarkAnsi),
    RiffetTheme("everforest", everforestLight, everforestDark, everforestLightAnsi, everforestDarkAnsi),
    RiffetTheme("kiln", kilnLight, kilnDark, kilnLightAnsi, kilnDarkAnsi),
    RiffetTheme("ink", inkLight, inkDark, inkLightAnsi, inkDarkAnsi),
    RiffetTheme("sepia", sepiaLight, sepiaDark, sepiaLightAnsi, sepiaDarkAnsi),
    RiffetTheme("moss", mossLight, mossDark, mossLightAnsi, mossDarkAnsi),
    RiffetTheme("slate", slateLight, slateDark, slateLightAnsi, slateDarkAnsi),
    RiffetTheme("pencil", pencilLight, pencilDark, pencilLightAnsi, pencilDarkAnsi),
    RiffetTheme("celadon", celadonLight, celadonDark, celadonLightAnsi, celadonDarkAnsi),
)

/** The theme a device starts on, and the fallback for an id this build does not know. */
val RiffetDefaultTheme: RiffetTheme = RiffetThemes.first()

fun riffetTheme(id: String?): RiffetTheme = RiffetThemes.firstOrNull { it.id == id } ?: RiffetDefaultTheme

/**
 * Builds a palette from a custom theme's stored role values. Null when a role is missing or
 * unreadable: a half-painted interface is worse than the default theme.
 */
fun riffetColors(roles: Map<String, String>): RiffetColors? {
    val bg = RiffetColorParsing.parse(roles["bg"]) ?: return null
    val bgSidebar = RiffetColorParsing.parse(roles["bg-sidebar"]) ?: return null
    val bgSubtle = RiffetColorParsing.parse(roles["bg-subtle"]) ?: return null
    val bgMuted = RiffetColorParsing.parse(roles["bg-muted"]) ?: return null
    val bgElevated = RiffetColorParsing.parse(roles["bg-elevated"]) ?: return null
    val bgPopover = RiffetColorParsing.parse(roles["bg-popover"]) ?: return null
    val bgHover = RiffetColorParsing.parse(roles["bg-hover"]) ?: return null
    val bgActive = RiffetColorParsing.parse(roles["bg-active"]) ?: return null
    val bgBubble = RiffetColorParsing.parse(roles["bg-bubble"]) ?: return null
    val fg = RiffetColorParsing.parse(roles["fg"]) ?: return null
    val fg2 = RiffetColorParsing.parse(roles["fg-2"]) ?: return null
    val fg3 = RiffetColorParsing.parse(roles["fg-3"]) ?: return null
    val fg4 = RiffetColorParsing.parse(roles["fg-4"]) ?: return null
    val line = RiffetColorParsing.parse(roles["line"]) ?: return null
    val lineSoft = RiffetColorParsing.parse(roles["line-soft"]) ?: return null
    val lineStrong = RiffetColorParsing.parse(roles["line-strong"]) ?: return null
    val primary = RiffetColorParsing.parse(roles["primary"]) ?: return null
    val primaryHover = RiffetColorParsing.parse(roles["primary-hover"]) ?: return null
    val primaryFg = RiffetColorParsing.parse(roles["primary-fg"]) ?: return null
    val accent = RiffetColorParsing.parse(roles["accent"]) ?: return null
    val accentHover = RiffetColorParsing.parse(roles["accent-hover"]) ?: return null
    val accentSoft = RiffetColorParsing.parse(roles["accent-soft"]) ?: return null
    val accentFg = RiffetColorParsing.parse(roles["accent-fg"]) ?: return null
    val success = RiffetColorParsing.parse(roles["success"]) ?: return null
    val successSoft = RiffetColorParsing.parse(roles["success-soft"]) ?: return null
    val warning = RiffetColorParsing.parse(roles["warning"]) ?: return null
    val warningSoft = RiffetColorParsing.parse(roles["warning-soft"]) ?: return null
    val danger = RiffetColorParsing.parse(roles["danger"]) ?: return null
    val dangerSoft = RiffetColorParsing.parse(roles["danger-soft"]) ?: return null
    val dangerFg = RiffetColorParsing.parse(roles["danger-fg"]) ?: return null
    val diffAdd = RiffetColorParsing.parse(roles["diff-add"]) ?: return null
    val diffAddGutter = RiffetColorParsing.parse(roles["diff-add-gutter"]) ?: return null
    val diffAddMarker = RiffetColorParsing.parse(roles["diff-add-marker"]) ?: return null
    val diffAddStrong = RiffetColorParsing.parse(roles["diff-add-strong"]) ?: return null
    val diffDel = RiffetColorParsing.parse(roles["diff-del"]) ?: return null
    val diffDelGutter = RiffetColorParsing.parse(roles["diff-del-gutter"]) ?: return null
    val diffDelMarker = RiffetColorParsing.parse(roles["diff-del-marker"]) ?: return null
    val diffDelStrong = RiffetColorParsing.parse(roles["diff-del-strong"]) ?: return null
    val toast = RiffetColorParsing.parse(roles["toast"]) ?: return null
    val toastSuccess = RiffetColorParsing.parse(roles["toast-success"]) ?: return null
    val toastDanger = RiffetColorParsing.parse(roles["toast-danger"]) ?: return null
    val agentCursor = RiffetColorParsing.parse(roles["agent-cursor"]) ?: return null
    val agentCodex = RiffetColorParsing.parse(roles["agent-codex"]) ?: return null
    val agentClaude = RiffetColorParsing.parse(roles["agent-claude"]) ?: return null
    val agentDsh = RiffetColorParsing.parse(roles["agent-dsh"]) ?: return null
    val chart1 = RiffetColorParsing.parse(roles["chart-1"]) ?: return null
    val chart2 = RiffetColorParsing.parse(roles["chart-2"]) ?: return null
    val chart3 = RiffetColorParsing.parse(roles["chart-3"]) ?: return null
    val chart4 = RiffetColorParsing.parse(roles["chart-4"]) ?: return null
    val chart5 = RiffetColorParsing.parse(roles["chart-5"]) ?: return null
