        accent = accent,
        accentHover = accentHover,
        accentSoft = accentSoft,
        accentFg = accentFg,
        success = success,
        successSoft = successSoft,
        warning = warning,
        warningSoft = warningSoft,
        danger = danger,
        dangerSoft = dangerSoft,
        dangerFg = dangerFg,
        diffAdd = diffAdd,
        diffAddGutter = diffAddGutter,
        diffAddMarker = diffAddMarker,
        diffAddStrong = diffAddStrong,
        diffDel = diffDel,
        diffDelGutter = diffDelGutter,
        diffDelMarker = diffDelMarker,
        diffDelStrong = diffDelStrong,
        toast = toast,
        toastSuccess = toastSuccess,
        toastDanger = toastDanger,
        agentCursor = agentCursor,
        agentCodex = agentCodex,
        agentClaude = agentClaude,
        agentDsh = agentDsh,
        chart1 = chart1,
        chart2 = chart2,
        chart3 = chart3,
        chart4 = chart4,
        chart5 = chart5,
        chart6 = chart6,
        chart7 = chart7,
        chart8 = chart8,
    )
}

/** Parses a custom theme's ANSI list; null unless it holds exactly sixteen readable colours. */
fun riffetAnsi(colors: List<String>): RiffetAnsi? {
    if (colors.size != 16) return null
    return RiffetAnsi(colors.map { RiffetColorParsing.parse(it) ?: return null })
}

/** Font stacks are shipped verbatim; a platform resolves them to its own families. */
